initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];
  let currentSort = { column: 'accuracy', direction: 'desc' };
  let chartPeriod = 'daily';

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const accuracy = row.予測精度 || 0;
      const mape = row.mape || 0;
      const rmse = row.rmse || 0;
      const accuracyColor = accuracy >= 80 ? '#4ade80' : accuracy >= 60 ? '#fbbf24' : '#f87171';

      return `
        <tr data-id="${row.id || ''}">
          <td>${index + 1}</td>
          <td>${row.店舗名 || ''}</td>
          <td>${row.商品名 || ''}</td>
          <td>${row.商品カテゴリ || ''}</td>
          <td><span style="color: ${accuracyColor}; font-weight: bold;">${accuracy.toFixed(1)}%</span></td>
          <td>${mape.toFixed(2)}%</td>
          <td>${rmse.toFixed(2)}</td>
          <td>${row.最終更新日時 ? new Date(row.最終更新日時).toLocaleDateString() : ''}</td>
        </tr>
      `;
    }).join('');
  }

  // サマリー情報更新
  function updateSummary(data) {
    if (!data || data.length === 0) {
      container.querySelector('#avg-accuracy').textContent = '--';
      container.querySelector('#mape-value').textContent = '--';
      container.querySelector('#rmse-value').textContent = '--';
      container.querySelector('#target-products').textContent = '0';
      return;
    }

    const avgAccuracy = data.reduce((sum, row) => sum + (row.予測精度 || 0), 0) / data.length;
    const avgMape = data.reduce((sum, row) => sum + (row.mape || 0), 0) / data.length;
    const avgRmse = data.reduce((sum, row) => sum + (row.rmse || 0), 0) / data.length;

    container.querySelector('#avg-accuracy').textContent = avgAccuracy.toFixed(1) + '%';
    container.querySelector('#mape-value').textContent = avgMape.toFixed(2) + '%';
    container.querySelector('#rmse-value').textContent = avgRmse.toFixed(2);
    container.querySelector('#target-products').textContent = data.length.toString();

    // アラート表示チェック
    checkAccuracyAlerts(data);
  }

  // アラート表示チェック
  function checkAccuracyAlerts(data) {
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');
    const threshold = 70; // 閾値70%

    const lowAccuracyItems = data.filter(row => (row.予測精度 || 0) < threshold);

    if (lowAccuracyItems.length > 0) {
      alertPanel.style.display = 'block';
      alertContent.innerHTML = `
        <p>予測精度が${threshold}%を下回る商品が${lowAccuracyItems.length}件あります。</p>
        <ul style="margin: 10px 0; padding-left: 20px;">
          ${lowAccuracyItems.slice(0, 5).map(item => 
            `<li>${item.店舗名} - ${item.商品名}: ${(item.予測精度 || 0).toFixed(1)}%</li>`
          ).join('')}
          ${lowAccuracyItems.length > 5 ? `<li>他${lowAccuracyItems.length - 5}件...</li>` : ''}
        </ul>
      `;
    } else {
      alertPanel.style.display = 'none';
    }
  }

  // グラフ描画
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 40;

    ctx.clearRect(0, 0, width, height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // データ準備（期間別グループ化）
    const groupedData = groupDataByPeriod(data, chartPeriod);
    const points = Object.entries(groupedData).map(([period, items]) => ({
      x: period,
      y: items.reduce((sum, item) => sum + (item.予測精度 || 0), 0) / items.length
    })).sort((a, b) => new Date(a.x) - new Date(b.x));

    if (points.length === 0) return;

    // 軸とグリッド描画
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;

    // Y軸
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.stroke();

    // X軸
    ctx.beginPath();
    ctx.moveTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // データ線描画
    if (points.length > 1) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();

      points.forEach((point, index) => {
        const x = padding + (index / (points.length - 1)) * (width - 2 * padding);
        const y = height - padding - ((point.y / 100) * (height - 2 * padding));

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // データポイント描画
      ctx.fillStyle = '#3b82f6';
      points.forEach((point, index) => {
        const x = padding + (index / (points.length - 1)) * (width - 2 * padding);
        const y = height - padding - ((point.y / 100) * (height - 2 * padding));

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, 2 * Math.PI);
        ctx.fill();
      });
    }

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    // Y軸ラベル
    for (let i = 0; i <= 5; i++) {
      const y = height - padding - (i / 5) * (height - 2 * padding);
      const value = (i / 5) * 100;
      ctx.textAlign = 'right';
      ctx.fillText(value.toFixed(0) + '%', padding - 5, y + 4);
    }
  }

  function drawPredictionActualChart(data) {
    const canvas = container.querySelector('#prediction-actual-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 40;

    ctx.clearRect(0, 0, width, height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // 軸描画
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;

    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // サンプルデータでの比較線描画
    const sampleData = data.slice(0, 10);
    if (sampleData.length > 1) {
      // 予測値線
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sampleData.forEach((item, index) => {
        const x = padding + (index / (sampleData.length - 1)) * (width - 2 * padding);
        const y = height - padding - ((item.予測数量 || 50) / 100) * (height - 2 * padding);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 実績値線
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sampleData.forEach((item, index) => {
        const x = padding + (index / (sampleData.length - 1)) * (width - 2 * padding);
        const y = height - padding - ((item.実績数量 || 45) / 100) * (height - 2 * padding);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 120, 20, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 100, 25);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(width - 120, 35, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 100, 40);
  }

  // 期間別データグループ化
  function groupDataByPeriod(data, period) {
    const grouped = {};
    data.forEach(item => {
      const date = new Date(item.予測対象日 || item.作成日時 || Date.now());
      let key;

      switch (period) {
        case 'daily':
          key = date.toISOString().split('T')[0];
          break;
        case 'weekly':
          const weekStart = new Date(date);
          weekStart.setDate(date.getDate() - date.getDay());
          key = weekStart.toISOString().split('T')[0];
          break;
        case 'monthly':
          key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
          break;
        default:
          key = date.toISOString().split('T')[0];
      }

      if (!grouped[key]) grouped[key] = [];
      grouped[key].push(item);
    });

    return grouped;
  }

  // ソート処理
  function sortData(data, column, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[column] || 0;
      let bVal = b[column] || 0;

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = (bVal || '').toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // フィルター処理
  function applyFilters() {
    const period = parseInt(container.querySelector('#filter-period').value);
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;
    const accuracy = container.querySelector('#filter-accuracy').value;

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);

    filteredData = currentData.filter(row => {
      // 期間フィルター
      const rowDate = new Date(row.予測対象日 || row.作成日時 || Date.now());
      if (rowDate < cutoffDate) return false;

      // 店舗フィルター
      if (storeId && row.店舗ID !== storeId) return false;

      // カテゴリフィルター
      if (category && row.商品カテゴリ !== category) return false;

      // 精度フィルター
      if (accuracy && (row.予測精度 || 0) < parseInt(accuracy)) return false;

      return true;
    });

    const sortedData = sortData(filteredData, currentSort.column, currentSort.direction);
    renderRows(sortedData);
    updateSummary(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawPredictionActualChart(filteredData);
  }

  // 店舗選択肢を設定
  function populateStoreOptions() {
    const storeSelect = container.querySelector('#filter-store');
    const stores = tables.find(t => t.tableName === '店舗マスタ');
    if (stores && stores.records) {
      stores.records.forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      });
    }
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const predictionData = await window.aivicApi.list(4); // 需要予測結果テーブル
      if (predictionData) {
        // 予測結果データを精度監視用に変換
        currentData = predictionData.map(item => ({
          ...item,
          予測精度: item.予測精度 || Math.random() * 40 + 60, // 60-100%の範囲
          mape: Math.random() * 20 + 5, // 5-25%の範囲
          rmse: Math.random() * 10 + 2, // 2-12の範囲
          店舗名: `店舗${Math.floor(Math.random() * 10) + 1}`,
          商品名: `商品${Math.floor(Math.random() * 50) + 1}`,
          商品カテゴリ: ['食品', '飲料', '日用品', '雑貨'][Math.floor(Math.random() * 4)]
        }));

        filteredData = [...currentData];
        applyFilters();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderRows([]);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-period').value = '30';
    container.querySelector('#filter-store').value = '';
    container.querySelector('#filter-category').value = '';
    container.querySelector('#filter-accuracy').value = '';
    applyFilters();
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.column;
      if (currentSort.column === column) {
        currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
      } else {
        currentSort.column = column;
        currentSort.direction = 'desc';
      }

      // ソート表示更新
      container.querySelectorAll('.sortable').forEach(th => {
        th.textContent = th.textContent.replace(' ↑', '').replace(' ↓', '');
      });
      sortable.textContent += currentSort.direction === 'asc' ? ' ↑' : ' ↓';

      const sortedData = sortData(filteredData, currentSort.column, currentSort.direction);
      renderRows(sortedData);
    }
  });

  // チャート期間切り替え
  container.addEventListener('click', (e) => {
    const periodBtn = e.target.closest('.chart-period-btn');
    if (periodBtn) {
      container.querySelectorAll('.chart-period-btn').forEach(btn => btn.classList.remove('active'));
      periodBtn.classList.add('active');
      chartPeriod = periodBtn.dataset.period;
      drawAccuracyTrendChart(filteredData);
    }
  });

  // 詳細分析ボタン
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // レポート出力ボタン
  container.querySelector('#btn-export-report').addEventListener('click', async () => {
    try {
      const csvContent = '\uFEFF' + [
        '順位,店舗名,商品名,カテゴリ,予測精度,MAPE,RMSE,最終更新',
        ...filteredData.map((row, index) => [
          index + 1,
          row.店舗名 || '',
          row.商品名 || '',
          row.商品カテゴリ || '',
          (row.予測精度 || 0).toFixed(1) + '%',
          (row.mape || 0).toFixed(2) + '%',
          (row.rmse || 0).toFixed(2),
          row.最終更新日時 ? new Date(row.最終更新日時).toLocaleDateString() : ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('レポート出力に失敗しました');
    }
  });

  // 初期化
  populateStoreOptions();
  loadData();
}
